<?php if(!$appointmentRows): ?><p class="empty-state">Bu bölümde randevu bulunmuyor.</p><?php else: ?><div class="customer-appointment-list"><?php foreach($appointmentRows as$a): ?><article class="customer-appointment"><div class="appointment-date"><strong><?= e(date('d',strtotime($a['start_at']))) ?></strong><small><?= e(date('m.Y',strtotime($a['start_at']))) ?></small></div><div class="appointment-copy"><h3><?= e($a['service_name']) ?></h3><p><?= e($a['customer_name']) ?> · <?= e(date('H:i',strtotime($a['start_at'])).'–'.date('H:i',strtotime($a['end_at']))) ?></p><small>#<?= (int)$a['id'] ?> · <?= e($money($a['service_price'])) ?> tahmini hizmet tutarı</small></div><div class="appointment-actions"><span class="status-pill status-<?= e($a['status']) ?>"><?= e($labels[$a['status']]) ?></span><a class="btn btn-sm btn-outline-dark" href="<?= e(url('employee/appointments/detail?id='.$a['id'])) ?>">Detayı gör</a></div></article><?php endforeach ?></div><?php endif ?>
